def moyenne_attribut(table, attribut):
    if len(table) == 0:
        return None
    total = 0
    for ligne in table:
        total = total + ligne[attribut]
    return total / len(table)

assert moyenne_attribut([{'x': 2}, {'x': 4}], 'x') == 3
assert moyenne_attribut([], 'x') is None
